import { collection, doc, getDoc, getDocs, query, runTransaction, serverTimestamp, setDoc, updateDoc, where } from "firebase/firestore";
import { db } from "../../services/firebase";
import { cloneElement } from "react";

const removeKeyFromObject = (obj,key) => {
    const {[key]:_,...newObj} = obj
    return newObj
}

const stringifyItems = (items) => {
    return items.map(item => {
        return `${item.price} M${item.mild}x H${item.hot}x`
    }).join('\n')
}

export const customerExists = async (name,cell) => {
    const customerRef = collection(db,"customers")
    const q = query(customerRef,
        where("name","==",name),
        where("cell", "==",cell)
    )
    const querySnapShot = await getDocs(q)
    return !querySnapShot.empty
}

export const addOrder = async (customer,items,deliveryType) => {
    const itemsRef = doc(collection(db,"items"))
    const orderRef = doc(collection(db,"orders"))
    try {
        await runTransaction(db,async (transaction) => {
            const customerId = customer.id ? customer.id :await addOrUpdateCustomer(null,removeKeyFromObject(customer,"id"),transaction)
            transaction.set(itemsRef,{
                orderId:orderRef.id,
                ...items
            })

            transaction.set(orderRef,{
                items:stringifyItems(items),
                customerId,
                itemsId:itemsRef.id,
                customerName:customer.name,
                customerDepartment:customer?.department || "",
                customerCell:customer?.cell || "",
                itemsString:stringifyItems(items),
                createdAt:serverTimestamp(),
                total:items.reduce((a,b) => a + b.total,0),
                done:false,
                collected:false,
                paid:false,
                deliveryType
            })
        })
    } catch (error) {
        throw new Error(error.message)
    }
    
}

export const updateOrder = async (id,field,value) => {
    const orderRef = doc(db,"orders",id)
    await updateDoc(orderRef,{
        [field]:value
    })
}

export const addOrUpdateCustomer = async (id,details,transaction) => {
    if(transaction){
        if(id){
            const ref = doc(db,"customers",id)
            await transaction.set(ref, {
                ...details,
                updatedAt:serverTimestamp()
            })
            return id
        }else {
            const ref = doc(collection(db,"customers"))
            await transaction.set(ref, {
                ...details,
                createdAt:serverTimestamp()
            })
            return ref.id
        }
    }else {
        if(id){
            const ref = doc(db,"customers",id)
            await updateDoc(ref,{
                ...details,
                updatedAt:serverTimestamp()
            })
            return id
        }else {
            const ref = doc(collection(db,"customers"))
            await setDoc(ref,{
                ...details,
                createdAt:serverTimestamp()
            })
            return ref.id
        }
    }
}

export const getOrders = async () => {
    const ordersRef = collection(db,"orders")
    const ordersSnapShot = await getDocs(ordersRef)
    const ordersDocs = ordersSnapShot.docs.map(doc => ({
        id:doc.id,
        ...doc.data()
    }))
    return ordersDocs
}
