import React, { useEffect, useState } from "react";
import { getOrders, updateOrder } from "../OrderServer";
import "./Orders.css"
import { collection, onSnapshot, or, query } from "firebase/firestore";
import { db } from "../../../services/firebase";
import FabLink from "../../../Components/FAB/FabLink";

export default function OrdersPage(){
    const [orders,setOrders] = useState(null)

    useEffect(() => {
        const q = query(collection(db,"orders"))
        const unSubscribe = onSnapshot(q, (querySnapshot) => {
            querySnapshot.docChanges().forEach((change) => {
                const orderData = {id:change.doc.id, ...change.doc.data()}
                if(change.type === "added"){
                    setOrders(prev => [...(prev || []), orderData]);
                }
                if(change.type === "modified"){
                    setOrders(prev => prev?.map(order => order.id === change.doc.id ? orderData: order))
                }
                if(change.type === "removed"){
                    setOrders(prev => prev?.filter(order => order.id !== change.doc.id ))
                }
            })
        })

        return () => unSubscribe()
    },[]) 

    const toggleStatus = async (order,field) => {
        await updateOrder(order.id,field,!order[field])
    }

    

    return (
        <div className="ordersPage">
            <h1>
                Orders
            </h1>
            <div className="orders">
                {orders && 
                    orders?.map(order => (
                        <div className="order" key={order.id}>
                        <div className="customer-details">
                            <p className="name">{order.customerName}</p>
                            <div className="dep-cell">
				                <span className="department">{order.customerDepartment}</span>
				                <span className="cell">{order.customerCell}</span>
                            </div>
                        </div>
                        <div className="items">
                            <p>
                                {order.itemsString}
                            </p>
                        </div>
                        <span>
                            {order.deliveryType}
                        </span>
                        <div className="actions">
                            <label>
                                <span>
                                    Ready
                                </span>
                                <input
                                    type="checkbox"
                                    checked={order.done}
                                    onChange={() => toggleStatus(order,"done")}
                                />
                            </label>
                            <label>
                                <span>
                                    Collected
                                </span>
                                <input
                                    type="checkbox"
                                    checked={order.collected}
                                    onChange={() => toggleStatus(order,"collected")}
                                />
                            </label>
                            <label>
                                <span>
                                    Paid
                                </span>
                                <input
                                    type="checkbox"
                                    checked={order.paid}
                                    onChange={() => toggleStatus(order,"paid")}
                                />
                            </label>
                        </div>
                    </div>
                        ))
                    }
                
            </div>
            <FabLink
                to={"/new-order"}
            />
        </div>
    )
}
